// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  Img,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type ProductCardAnimationProps = Record<string, any>;

const ProductCardAnimation: React.FC<ProductCardAnimationProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
  brandName = "Malloy Studio",
  productName = "Evober",
  productPrice = "$199",
  productSubtitle = "Armchair, Striped, Dark Gray",
  websiteUrl = "reallygreatsite.com",
  chairImage = "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/velvet-sofa-chair-png.png",
  initialChairScale = 1,
  chairScale = 2.2,
  benefits = [
    "Premium striped fabric",
    "Ergonomic lumbar support",
    "Durable hardwood frame",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Animation Timing (Starts after 1 second)
  const animationStartFrame = fps * 1;
  const progress = spring({
    frame: frame - animationStartFrame,
    fps,
    config: {
      damping: 15,
      mass: 0.8,
      stiffness: 80,
    },
  });

  // --- Animation Calculations ---

  // Card Translation & Rotation
  // Card moves left by 12% of screen width and tilts back on its right side
  const cardTranslateX = interpolate(progress, [0, 1], [0, -width * 0.12]);
  const cardRotateY = interpolate(progress, [0, 1], [0, -8]);

  // Chair Breakout Transformation
  // Chair moves with the card initially, then breaks out to the right and down
  const chairRelativeTranslateX = interpolate(
    progress,
    [0, 1],
    [0, width * 0.08]
  );
  const chairTranslateX = cardTranslateX + chairRelativeTranslateX;
  const chairTranslateY = interpolate(progress, [0, 1], [0, height * 0.05]);
  const animatedChairScale = interpolate(
    progress,
    [0, 1],
    [initialChairScale, chairScale]
  );

  // Perspective shift: bottom of chair (legs) tilts toward the viewer
  const chairRotateX = interpolate(progress, [0, 1], [0, 12]);

  // Shadow Animation (Lives inside the card, follows the chair's relative movement)
  const shadowTranslateX = interpolate(progress, [0, 1], [0, width * 0.04]);
  const shadowScale = interpolate(progress, [0, 1], [1, 1.8]);
  const shadowOpacity = interpolate(progress, [0, 1], [0.3, 0.1]);

  // Dimensions
  const cardWidth = 520;
  const cardHeight = 740;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        perspective: "2500px", // Provides depth for rotateY and rotateX
        fontFamily: interFamily,
        transition: "none",
      }}
    >
      {/* Central Wrapper to keep sibling coordinates aligned */}
      <div
        style={{
          position: "relative",
          width: cardWidth,
          height: cardHeight,
          transition: "none",
        }}
      >
        {/* === CARD LAYER === */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundColor: "#FFFFFF",
            borderRadius: 40,
            padding: "48px 48px",
            display: "flex",
            flexDirection: "column",
            transform: `translateX(${cardTranslateX}px) rotateY(${cardRotateY}deg)`,
            transformStyle: "preserve-3d",
            transition: "none",
            boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
          }}
        >
          {/* Brand */}
          <div
            style={{
              textAlign: "center",
              fontSize: 22,
              fontWeight: 500,
              color: "#555",
              marginBottom: 40,
              letterSpacing: "0.02em",
              transition: "none",
            }}
          >
            {brandName}
          </div>

          {/* Title & Price Row */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "baseline",
              marginBottom: 8,
              transition: "none",
            }}
          >
            <div
              style={{
                fontSize: 42,
                fontWeight: 800,
                color: "#111",
                letterSpacing: "-0.03em",
                transition: "none",
              }}
            >
              {productName}
            </div>
            <div
              style={{
                fontSize: 34,
                fontWeight: 700,
                color: "#111",
                letterSpacing: "-0.02em",
                transition: "none",
              }}
            >
              {productPrice}
            </div>
          </div>

          {/* Subtitle */}
          <div
            style={{
              fontSize: 18,
              color: "#666",
              fontWeight: 400,
              transition: "none",
            }}
          >
            {productSubtitle}
          </div>

          {/* Gap for Chair */}
          <div style={{ flex: 1, position: "relative" }}>
            {/* Soft Shadow - Anchored to card, moves to follow chair mass */}
            <div
              style={{
                position: "absolute",
                bottom: 20,
                left: "50%",
                width: 280,
                height: 30,
                backgroundColor: "#000000",
                borderRadius: "50%",
                filter: "blur(18px)",
                transform: `translateX(calc(-50% + ${shadowTranslateX}px)) scale(${shadowScale})`,
                opacity: shadowOpacity,
                transition: "none",
              }}
            />
          </div>

          {/* Website */}
          <div
            style={{
              textAlign: "center",
              fontSize: 18,
              color: "#888",
              fontWeight: 500,
              marginTop: "auto",
              transition: "none",
            }}
          >
            {websiteUrl}
          </div>
        </div>

        {/* === CHAIR LAYER === */}
        {/* Positioned as a sibling to break out of the card's bounds and rotation */}
        <div
          style={{
            position: "absolute",
            top: 180,
            left: 20,
            right: 20,
            bottom: 120,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transform: `translateX(${chairTranslateX}px) translateY(${chairTranslateY}px) scale(${animatedChairScale}) rotateX(${chairRotateX}deg)`,
            transformOrigin: "center center",
            pointerEvents: "none",
            transition: "none",
            zIndex: 10, // Ensures it renders above the right side of the card when overlapping
          }}
        >
          <Img
            src={chairImage}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "contain",
              transition: "none",
            }}
          />
        </div>
      </div>

      {/* === BENEFITS LAYER === */}
      {/* Properly aligned list of benefits dynamically mapping to real layout */}
      <div
        style={{
          position: "absolute",
          left: width * 0.58, // Precise alignment safely outside the scaled chair area
          top: "50%",
          transform: "translateY(-50%)",
          display: "flex",
          flexDirection: "column",
          gap: height * 0.05,
          zIndex: 20,
          transition: "none",
        }}
      >
        {benefits.map((benefit, i) => {
          // Stagger benefits to animate in right after the chair breakout starts
          const itemStart = fps * 1.5 + i * 6;

          const itemProg = spring({
            frame: frame - itemStart,
            fps,
            config: { damping: 14, stiffness: 90, mass: 0.8 },
          });

          // Using standard interpolation for opacity to avoid spring bounce artifacts on transparency
          const opacity = interpolate(frame - itemStart, [0, 15], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const translateX = interpolate(itemProg, [0, 1], [60, 0]);

          return (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 24, // Clear separation from list marker
                opacity,
                transform: `translateX(${translateX}px)`,
                transition: "none",
              }}
            >
              {/* Refined bullet point for proper list alignment structure */}
              <div
                style={{
                  width: 14,
                  height: 14,
                  backgroundColor: "#FFFFFF",
                  borderRadius: "50%",
                  flexShrink: 0,
                  transition: "none",
                }}
              />
              <div
                style={{
                  color: "#FFFFFF",
                  fontSize: 42,
                  fontWeight: 500,
                  letterSpacing: "-0.02em",
                  lineHeight: 1.2,
                  transition: "none",
                  whiteSpace: "normal",
                  maxWidth: width * 0.35, // Ensures text wraps cleanly rather than overflowing canvas
                }}
              >
                {benefit}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ProductCardAnimation;